package schema

const EraSchemaSQL = "-- Generated from blueprint. Review before applying.\nCREATE TABLE IF NOT EXISTS era (\n    id INTEGER PRIMARY KEY AUTOINCREMENT,\n    slug TEXT NOT NULL,\n    title TEXT NOT NULL,\n    sort_order INTEGER NOT NULL,\n    theme_json TEXT NOT NULL,\n    UNIQUE (slug)\n);\n\nCREATE TABLE IF NOT EXISTS album (\n    id INTEGER PRIMARY KEY AUTOINCREMENT,\n    era_id INTEGER NOT NULL,\n    title TEXT NOT NULL,\n    sort_order INTEGER NOT NULL,\n    FOREIGN KEY (era_id) REFERENCES era(id) ON DELETE CASCADE\n);\n\nCREATE TABLE IF NOT EXISTS media (\n    id INTEGER PRIMARY KEY AUTOINCREMENT,\n    album_id INTEGER NOT NULL,\n    kind TEXT NOT NULL CHECK (kind IN ('photo', 'short')),\n    content_hash TEXT NOT NULL,\n    duration_s INTEGER,\n    caption TEXT,\n    sort_order INTEGER NOT NULL,\n    UNIQUE (content_hash),\n    FOREIGN KEY (album_id) REFERENCES album(id) ON DELETE CASCADE\n);\n\nCREATE TABLE IF NOT EXISTS comment (\n    id INTEGER PRIMARY KEY AUTOINCREMENT,\n    media_id INTEGER NOT NULL,\n    user_id INTEGER NOT NULL,\n    body TEXT NOT NULL,\n    created_at TEXT NOT NULL,\n    FOREIGN KEY (media_id) REFERENCES media(id) ON DELETE CASCADE,\n    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE\n);\n\nCREATE TABLE IF NOT EXISTS layout_frame (\n    id INTEGER PRIMARY KEY AUTOINCREMENT,\n    region TEXT NOT NULL CHECK (region IN ('top', 'bottom', 'left', 'right', 'center')),\n    feature TEXT NOT NULL,\n    visible INTEGER NOT NULL,\n    config_json TEXT NOT NULL,\n    UNIQUE (region)\n);"
